  const stock=new Map(), custom=new Map();
  function sprite(type) {
    if(!stock.has(type)){
      const a=document.createElement("canvas"); a.width=a.height=32; const c=a.getContext("2d");
      if(["ghost","powerGhost","superGhost"].includes(type))ghost(c,{powerGhost:"power",superGhost:"super"}[type]);
      else if(type==="power"||type==="super")flame(c,type);
      else if(type==="yura")yura(c);else enemy(c,type);
      stock.set(type,a);
      if(O.config.images[type]){
        const img=new Image();
        img.onload=()=>{custom.set(type,img);window.dispatchEvent(new Event("obake-art-loaded"));};
        img.src=O.config.images[type];
      }
    }
    return custom.get(type)||stock.get(type);
  }
  function blit(c,type,x,y,w,h=w,mirror=false) {
    x=Math.round(x); y=Math.round(y);
    c.imageSmoothingEnabled=false;
    if (mirror) {
      c.save(); c.translate(x+w,y); c.scale(-1,1);
      c.drawImage(sprite(type),0,0,w,h); c.restore();
    } else c.drawImage(sprite(type),x,y,w,h);
  }
  function pagoda(c,x,y,scale,color) {
    c.save();c.translate(x,y);c.scale(scale,scale);
    rect(c,color,-2,-46,3,12);
    for(let i=0;i<3;i++){const w=9+i*5,top=-36+i*11;
      poly(c,color,[[-w,top+5],[-w+2,top+7],[-4,top+3],[0,top],[4,top+3],[w-2,top+7],[w,top+5],[w-1,top+9],[-w+1,top+9]]);
      rect(c,color,-w+5,top+8,2*w-10,5);}
    rect(c,color,-10,-4,20,9); c.restore();
  }
  function mountain(c,rng,w,h,base,amp,color,step) {
    const pts=[[0,h],[0,base]]; let prev=base;
    for(let x=0;x<=w+step;x+=step){
      const y=base+rng.int(-amp,amp);
      for(let k=1;k<=4;k++){const xx=x-step+k*step/4;pts.push([xx,prev+(y-prev)*k/4],[xx+2,prev+(y-prev)*k/4]);}prev=y;
    }
    pts.push([w,h]);poly(c,color,pts);
  }
  function pine(c,x,y,h,color){
    rect(c,color,x-1,y-h+3,3,h-1);
    for(let i=0;i<4;i++){const top=y-h+i*h/6,w=Math.round(h*(0.09+0.045*i));
      poly(c,color,[[x,top],[x+w,top+h*0.37],[x+2,top+h*0.32],[x,top+h*0.38],[x-2,top+h*0.32],[x-w,top+h*0.37]]);}
  }
  function landscape(c,w,h,title) {
    const rng=new O.Random(446), grd=c.createLinearGradient(0,0,0,h);
    grd.addColorStop(0,"#24203e");grd.addColorStop(.54,"#594467");grd.addColorStop(.8,"#a26d86");grd.addColorStop(1,"#674765");
    c.fillStyle=grd;c.fillRect(0,0,w,h);
    const mx=Math.floor(w*.77),my=Math.floor(h*.30),r=Math.floor(h*(title?.17:.11));
    disk(c,"#aa8393",mx,my,r+2);disk(c,"#ffdda9",mx,my,r);
    for(let i=0;i<22;i++){
      const dx=rng.int(-r,r),dy=rng.int(-r,r);
      if(dx*dx+dy*dy<r*r*.75)rect(c,"#f3c89f",mx+dx,my+dy,rng.int(1,5),1);
    }
    for(let i=0;i<w*.28;i++){
      const x=rng.int(0,w),y=rng.int(2,h*.65|0);
      if((x-mx)**2+(y-my)**2<(r+6)**2)continue;
      if(i%12===0)star(c,x,y,"#ffdba7",2);else rect(c,["#9b88a9","#e3b6b3","#b99bb9"][i%3],x,y,1,1);
    }
    for(let i=0;i<17;i++){const x=rng.int(0,w),y=rng.int(h*.26|0,h*.60|0),n=rng.int(9,37);
      rect(c,"#ab8498",x,y,n,1);rect(c,"#9b798f",x+3,y+2,n+9,1);}
    mountain(c,rng,w,h,h*.66,h*.11|0,"#735876",32);
    mountain(c,rng,w,h,h*.75,h*.10|0,"#614966",26);
    pagoda(c,w*.92,h*.77,.78,"#493951");
    mountain(c,rng,w,h,h*.84,h*.075|0,"#493951",19);
    for(let i=0;i<52;i++){const x=rng.int(0,w);pine(c,x,h*.93+rng.int(-5,4),rng.int(8,23),"#42354e");}
    mountain(c,rng,w,h,h*.93,5,"#352d45",13);
  }
  function lantern(c,x,y) {
    rect(c,"#302439",x-2,y-16,4,19);rect(c,"#a77e80",x-1,y-16,1,17);
    rect(c,"#302439",x-5,y-15,10,8);rect(c,gold,x-3,y-14,6,6);
    rect(c,"#cf8c69",x,y-14,1,6);rect(c,paper,x-2,y-13,1,3);
    poly(c,"#463148",[[x-7,y-15],[x-5,y-18],[x,y-21],[x+5,y-18],[x+7,y-15]]);
    rect(c,"#cb9c90",x-5,y-17,10,1);rect(c,"#8e6d79",x-5,y-7,10,2);
  }
  function titleScene(c,w,h) {
    landscape(c,w,h,true);

    // 由良ちゃんの霊視窓
    const wx=Math.round(w*.44)-42;
    const wy=Math.round(h*.26)-42;
    yuraTitleWipe(c,wx,wy);

    star(c,wx+5,wy+8,gold,3);
    star(c,wx+83,wy+18,gold,3);
    star(c,wx-3,wy+70,gold,3);
    star(c,wx+77,wy+79,paper,2);

    const start=Math.floor(w*.47);
    const bridgeTop=x=>Math.floor(h*(.99-.19*Math.sin((x-start)/(w-start)*2.4)));
    for(let x=start;x<w;x+=2){
      const y=bridgeTop(x);
      rect(c,"#31293e",x,y,2,h-y);rect(c,"#b89999",x,y,2,2);
      rect(c,"#735c70",x,y+2,2,3);if(x%14>1)rect(c,"#57465b",x,y+6,2,3);
      if(x%16>1)rect(c,"#4d4055",x,y+10,2,3);
    }
    lantern(c,w*.58|0,h*.91|0);lantern(c,w*.94|0,h*.83|0);
    const centerX=Math.round(w*.78);
    // The 32 px sprite has two transparent rows below its feet.
    blit(c,"ghost",centerX-16,bridgeTop(centerX)-30,32);
    const x=w*.70|0,y=h*.35|0,span=h*.47|0;
    blit(c,"super",x-21,y+33,22);blit(c,"power",x+span-2,y+21,15);
    star(c,x+7,y+19,gold,3);star(c,x+span-4,y+6,paper,3);star(c,x+span+12,y+47,gold,2);
    const rng=new O.Random(180);
    for(const side of [0,1]){
      for(let i=0;i<35;i++){
        const x=side?w-rng.int(0,42):rng.int(0,38),y=h-rng.int(0,14);
        rect(c,"#3c334b",x,y-5,2,12);rect(c,"#766b84",x-2,y-2,3,1);
        if(i%3===0){rect(c,rose,x-1,y-5,3,1);rect(c,"#eed2b1",x,y-6,1,3);}
      }
    }
  }
